const FACES = ["U", "R", "F", "D", "L", "B"] as const;
const SUFFIXES = ["", "2", "'"];
const COLOR: Record<(typeof FACES)[number], string> = { U: "#f7f3e9", R: "#d95743", F: "#1ba77a", D: "#e7c34f", L: "#ed8e42", B: "#3b6fc7" };
const AVERAGES = [5, 12, 50, 100] as const;
const SPEED_PHASES: SplitPhase[] = ["Cross", "F2L", "OLL", "PLL"];
const DEFAULT_PHASE_TARGETS: Record<SplitPhase, number> = { Cross: 4, F2L: 12, OLL: 4, PLL: 5 };
const TARGET_PRESETS: Record<"Beginner" | "Intermediate" | "Advanced", Record<SplitPhase, number>> = {
  Beginner: { Cross: 8, F2L: 30, OLL: 10, PLL: 12 },
  Intermediate: { Cross: 4, F2L: 12, OLL: 4, PLL: 5 },
  Advanced: { Cross: 2, F2L: 7, OLL: 2, PLL: 3 },
};
type PracticeMode = "full" | "cross" | "last-layer";
type TimerWcaRecord = { eventId: string; singleCentiseconds: number | null; averageCentiseconds: number | null };

function sameAxis(a: string, b: string) { const axis = (face: string) => (face === "U" || face === "D" ? 0 : face === "R" || face === "L" ? 1 : 2); return axis(a) === axis(b); }
function newScramble() { const moves: string[] = []; while (moves.length < 20) { const face = FACES[Math.floor(Math.random() * FACES.length)]; const previous = moves.at(-1)?.[0]; const before = moves.at(-2)?.[0]; if (face === previous || (previous && before && sameAxis(face, previous) && sameAxis(face, before))) continue; moves.push(face + SUFFIXES[Math.floor(Math.random() * SUFFIXES.length)]); } return moves.join(" "); }
function csvCell(value: string | number) { return `"${String(value).replaceAll('"', '""')}"`; }
function progressSeries(entries: SolveHistoryEntry[]) { const ordered = [...entries].reverse(); return ordered.map((entry, index) => { const point: Record<string, number | null | undefined> = { solve: index + 1, single: effectiveTime(entry) }; for (const size of AVERAGES) point[`ao${size}`] = index + 1 < size ? undefined : rollingAverage(ordered.slice(index + 1 - size, index + 1)); return point; }); }
function saveFile(name: string, type: string, value: string) { const url = URL.createObjectURL(new Blob([value], { type })); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url); }
function canvasLines(context: CanvasRenderingContext2D, text: string, maxWidth: number) { const words = text.trim().split(/\s+/).filter(Boolean); const lines: string[] = []; let line = ""; for (const word of words) { const candidate = line ? `${line} ${word}` : word; if (line && context.measureText(candidate).width > maxWidth) { lines.push(line); line = word; } else line = candidate; } if (line) lines.push(line); return lines; }
function drawMetricCube(context: CanvasRenderingContext2D, state: string, x: number, y: number, tile: number) { const safe = state.length === 54 ? state : SOLVED_FAST_STATE; const faces = ["U", "R", "F", "D", "L", "B"] as const; const positions = { U: [1, 0], L: [0, 1], F: [1, 1], R: [2, 1], B: [3, 1], D: [1, 2] } as const; const offsets = { U: 0, R: 9, F: 18, D: 27, L: 36, B: 45 } as const; context.fillStyle = "#17221d"; context.fillRect(x - 8, y - 8, tile * 12 + 16, tile * 9 + 16); for (const face of faces) { const [column, row] = positions[face]; for (let index = 0; index < 9; index += 1) { const sticker = safe[offsets[face] + index] ?? "U"; const sx = x + (column * 3 + (index % 3)) * tile; const sy = y + (row * 3 + Math.floor(index / 3)) * tile; context.fillStyle = CUBE_COLOR[sticker] ?? "#888"; context.fillRect(sx, sy, tile - 1, tile - 1); } } }
function exportAo5Image(entries: SolveHistoryEntry[], exclusions: Record<string, "best" | "worst">, value: number | null | undefined, vi: boolean) { const width = 3200; const headerHeight = 320; const rowHeight = 330; const footerHeight = 150; const canvas = document.createElement("canvas"); canvas.width = width; canvas.height = headerHeight + entries.length * rowHeight + footerHeight; const context = canvas.getContext("2d"); if (!context) return; const margin = 100; const cubeX = 690; const scrambleX = 1120; const scrambleWidth = width - scrambleX - margin; context.fillStyle = "#f4f0e8"; context.fillRect(0, 0, canvas.width, canvas.height); context.strokeStyle = "rgba(23,34,29,.12)"; context.lineWidth = 1; for (let x = 0; x < width; x += 64) { context.beginPath(); context.moveTo(x, 0); context.lineTo(x, canvas.height); context.stroke(); } context.fillStyle = "#17221d"; context.fillRect(0, 0, width, 22); context.fillRect(margin, 62, width - margin * 2, 184); context.fillStyle = "#1ba77a"; context.font = "700 32px monospace"; context.fillText("CFOP SOLVER STUDIO · TIMER RECORD", 148, 118); context.fillStyle = "#f4f0e8"; context.font = "800 84px monospace"; context.fillText(`AO5 · ${value == null ? "DNF" : formatSolveTime(value)}`, 148, 204); context.fillStyle = "rgba(244,240,232,.72)"; context.font = "600 24px monospace"; context.fillText(vi ? "BẢNG NGANG · SCRAMBLE VÀ CUBENET TOÀN KHỔ" : "WIDE SHEET · FULL-WIDTH SCRAMBLES AND CUBENETS", 150, 236); entries.forEach((entry, index) => { const top = headerHeight + index * rowHeight; const exclusion = exclusions[entry.id]; context.fillStyle = index % 2 ? "#ebe5d9" : "#fffdfa"; context.fillRect(margin, top + 12, width - margin * 2, rowHeight - 24); context.strokeStyle = exclusion === "best" ? "#1ba77a" : exclusion === "worst" ? "#d95743" : "rgba(23,34,29,.28)"; context.lineWidth = exclusion ? 7 : 3; context.strokeRect(margin, top + 12, width - margin * 2, rowHeight - 24); context.fillStyle = exclusion === "best" ? "#176d52" : exclusion === "worst" ? "#a33d2d" : "#17221d"; context.font = "900 34px monospace"; context.fillText(String(index + 1).padStart(2, "0"), 150, top + 82); context.font = "900 58px monospace"; context.fillText(formatSolveResult(entry), 150, top + 153); context.font = "700 19px monospace"; context.fillStyle = "#65716a"; context.fillText(new Date(entry.createdAt).toLocaleDateString(vi ? "vi-VN" : "en-US"), 152, top + 196); context.fillStyle = exclusion === "best" ? "#176d52" : exclusion === "worst" ? "#a33d2d" : "#65716a"; context.font = "700 18px monospace"; context.fillText(exclusion ? (exclusion === "best" ? (vi ? "BEST · LOẠI" : "BEST · DISCARDED") : (vi ? "WORST · LOẠI" : "WORST · DISCARDED")) : (vi ? "TÍNH VÀO AO" : "COUNTED IN AO"), 150, top + 244); drawMetricCube(context, safeScrambleState(entry.input), cubeX, top + 26, 28); context.fillStyle = "#1b7b5e"; context.font = "800 20px monospace"; context.fillText("SCRAMBLE", scrambleX, top + 64); context.fillStyle = "#17221d"; context.font = "900 36px monospace"; const scramble = canvasLines(context, entry.input, scrambleWidth).slice(0, 2); scramble.forEach((line, lineIndex) => context.fillText(line, scrambleX, top + 126 + lineIndex * 50)); context.fillStyle = "#65716a"; context.font = "700 19px monospace"; context.fillText(entry.phaseSplits.length ? splitSummary(entry) : (vi ? "Không có phase split" : "No phase splits"), scrambleX, top + 245); if (entry.note) { context.font = "600 18px monospace"; context.fillText(`${vi ? "GHI CHÚ" : "NOTE"}: ${entry.note.slice(0, 132)}`, scrambleX, top + 280); } }); context.fillStyle = "#65716a"; context.font = "600 21px monospace"; context.fillText(vi ? "BEST/WORST được loại theo quy tắc Ao5 · Xuất từ CFOP Solver Studio" : "BEST/WORST are discarded under Ao5 rules · Exported from CFOP Solver Studio", margin, canvas.height - 54); const link = document.createElement("a"); link.download = `cfop-ao5-${Date.now()}.png`; link.href = canvas.toDataURL("image/png"); link.click(); }
function safeScrambleState(scramble: string) { try { return stateFromScramble(scramble); } catch { return SOLVED_FAST_STATE; } }
function initialStateFor(entry: SolveHistoryEntry) { return entry.inputKind === "state" && entry.input.length === 54 ? entry.input : stateFromScramble(entry.input); }
function splitSummary(entry: SolveHistoryEntry) { return entry.phaseSplits.map((split) => `${split.phase} ${(split.elapsedMs / 1000).toFixed(2)}s`).join(" · "); }
function readPhaseTargets(): Record<SplitPhase, number> { try { const saved = JSON.parse(localStorage.getItem("cfop-phase-targets") ?? "{}") as Partial<Record<SplitPhase, unknown>>; return Object.fromEntries(SPEED_PHASES.map((phase) => [phase, typeof saved[phase] === "number" && saved[phase] > 0 && saved[phase] < 120 ? saved[phase] : DEFAULT_PHASE_TARGETS[phase]])) as Record<SplitPhase, number>; } catch { return DEFAULT_PHASE_TARGETS; } }
function phaseProgressSeries(entries: SolveHistoryEntry[]) { return [...entries].reverse().map((entry, index) => { const point: Record<string, number | undefined> = { solve: index + 1 }; entry.phaseSplits.forEach((split) => { point[split.phase] = split.elapsedMs; }); return point; }); }
function phaseAverage(values: number[], windowSize: 5 | 12) { if (values.length < windowSize) return undefined; const sample = values.slice(0, windowSize).sort((a, b) => a - b); const core = sample.slice(1, -1); return core.reduce((sum, value) => sum + value, 0) / core.length; }
function phaseStability(entries: SolveHistoryEntry[]) { return Object.fromEntries(SPEED_PHASES.map((phase) => { const values = entries.flatMap((entry) => entry.phaseSplits.filter((split) => split.phase === phase).map((split) => split.elapsedMs)); return [phase, { count: values.length, ao5: phaseAverage(values, 5), ao12: phaseAverage(values, 12) }]; })) as Record<SplitPhase, { count: number; ao5: number | undefined; ao12: number | undefined }>; }
const MOVE_TOKEN = /(?:[URFDLBMESxyz](?:w)?(?:2|')?)/g;
function solutionMoves(solution: string) { return solution.match(MOVE_TOKEN) ?? []; }
function solutionEfficiency(entry: SolveHistoryEntry) { const moves = solutionMoves(entry.solution).length; const seconds = entry.elapsedMs / 1000; const tps = moves && seconds > 0 ? moves / seconds : 0; const label = !moves ? "—" : moves <= 45 && tps >= 3 ? "STRONG" : moves <= 60 || tps >= 2.5 ? "STEADY" : "REFINE"; return { moves, tps, label }; }
type PhaseTps = { phase: "Cross" | "F2L" | "OLL" | "PLL"; tps: number; moves: number; seconds: number };
function phaseTpsFromSolution(solution: string): PhaseTps[] {
  const buckets = new Map<PhaseTps["phase"], { moves: number; seconds: number }>();
  for (const part of solution.split(/[|;\n]+/)) {
    const match = part.trim().match(/^(Cross|F2L(?:\s*[1-4])?|OLL|PLL)\s*(?:@|:)\s*([0-9]+(?:\.[0-9]+)?)s?\s*(.*)$/i);
    if (!match) continue;
    const phase = match[1].toUpperCase().startsWith("F2L") ? "F2L" : (match[1][0].toUpperCase() + match[1].slice(1).toLowerCase()) as PhaseTps["phase"];
    const moves = (match[3].match(/(?:[URFDLBMESxyz](?:w)?(?:2|')?)/g) ?? []).length;
    const seconds = Number(match[2]);
    if (moves > 0 && seconds > 0) { const current = buckets.get(phase) ?? { moves: 0, seconds: 0 }; current.moves += moves; current.seconds += seconds; buckets.set(phase, current); }
  }
  return (["Cross", "F2L", "OLL", "PLL"] as const).flatMap((phase) => { const item = buckets.get(phase); return item ? [{ phase, ...item, tps: item.moves / item.seconds }] : []; });
}

export default function TimerLab() {
  const { language } = useLanguage();
  const vi = language === "vi";
  const accountQuery = trpc.cfopAccount.me.useQuery(undefined, { staleTime: 30_000, retry: false });
  const wcaProfileQuery = trpc.cfopAccount.wca.profile.useQuery(undefined, { enabled: Boolean(accountQuery.data?.wcaId), staleTime: 10 * 60 * 1000, retry: false });
  const [eventId, setEventId] = useState<TimerEventId>(() => normalizeTimerEventId(localStorage.getItem("cfop-timer-event")));
  const [scramble, setScramble] = useState(newScramble);
  const [scrambleLoading, setScrambleLoading] = useState(false);
  const [scrambleError, setScrambleError] = useState("");
  const [entries, setEntries] = useState<SolveHistoryEntry[]>(() => readSolveHistory());
  const [timerVersion, setTimerVersion] = useState(0);
  const [saved, setSaved] = useState(false);
  const [latestRecorded, setLatestRecorded] = useState<SolveHistoryEntry | null>(null);
  const [personalRecords, setPersonalRecords] = useState<PersonalRecord[]>([]);
  const [selectedMetric, setSelectedMetric] = useState<TimerMetricKey | null>(null);
  const [copiedScrambleId, setCopiedScrambleId] = useState<string | null>(null);
  const [showMetricCubeNets, setShowMetricCubeNets] = useState(() => localStorage.getItem("cfop-metric-cubenets") !== "off");
  const [expandedMetricCube, setExpandedMetricCube] = useState<SolveHistoryEntry | null>(null);
  const [inspectionColor, setInspectionColor] = useState<(typeof FACES)[number]>(() => { const saved = localStorage.getItem("cfop-inspection-color"); return FACES.includes(saved as (typeof FACES)[number]) ? saved as (typeof FACES)[number] : "U"; });
  const [crossHighlight, setCrossHighlight] = useState(() => localStorage.getItem("cfop-cross-highlight") !== "off");
  const [inspectionSound, setInspectionSound] = useState(() => localStorage.getItem("cfop-inspection-sound") !== "off");
  const [spaceSplits, setSpaceSplits] = useState(() => localStorage.getItem("cfop-space-splits") !== "off");
  const [phaseTargets, setPhaseTargets] = useState<Record<SplitPhase, number>>(readPhaseTargets);
  const [practiceMode, setPracticeMode] = useState<PracticeMode>("full");
  const [practiceCase, setPracticeCase] = useState<PracticeCase | null>(null);
  const [editing, setEditing] = useState<SolveHistoryEntry | null>(null);
  const [editSeconds, setEditSeconds] = useState("");
  const [editPenalty, setEditPenalty] = useState<SolvePenalty>("none");
  const [editSolution, setEditSolution] = useState("");
  const [editNote, setEditNote] = useState("");
  const [editTags, setEditTags] = useState("");
  const [deleteTarget, setDeleteTarget] = useState<SolveHistoryEntry | null>(null);
  const [bulkDeleteOpen, setBulkDeleteOpen] = useState(false);
  const [importError, setImportError] = useState("");
  const [tagFilter, setTagFilter] = useState("all");
  const [noteQuery, setNoteQuery] = useState("");
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => new Set());
  const [replay, setReplay] = useState<SolveHistoryEntry | null>(null);
  const [replayStep, setReplayStep] = useState(0);
  const [replayPlaying, setReplayPlaying] = useState(false);
  const [replaySpeed, setReplaySpeed] = useState(1);
  const [location] = useLocation();
  const labTab: "timer" | "study" = location.split("?")[0] === "/study" ? "study" : "timer";
  const [solutionError, setSolutionError] = useState("");
  const fileRef = useRef<HTMLInputElement>(null);
  const scrambleRequest = useRef(0);

  const isThreeByThree = isThreeByThreeEvent(eventId);
  const eventLabel = timerEventLabel(eventId, language);
  const state = useMemo(() => { if (!isThreeByThree) return SOLVED_FAST_STATE; try { return stateFromScramble(scramble); } catch { return SOLVED_FAST_STATE; } }, [isThreeByThree, scramble]);
  const eventEntries = useMemo(() => filterTimerEventEntries(entries, eventId), [entries, eventId]);
  const allTags = useMemo(() => Array.from(new Set(eventEntries.flatMap((entry) => entry.tags))).sort((a, b) => a.localeCompare(b)), [eventEntries]);
  const visibleEntries = useMemo(() => { const needle = noteQuery.trim().toLocaleLowerCase(); return eventEntries.filter((entry) => (tagFilter === "all" || entry.tags.includes(tagFilter)) && (!needle || entry.note.toLocaleLowerCase().includes(needle) || entry.tags.some((tag) => tag.toLocaleLowerCase().includes(needle)))); }, [eventEntries, noteQuery, tagFilter]);
  const progress = useMemo(() => progressSeries(visibleEntries), [visibleEntries]);
  const phaseProgress = useMemo(() => phaseProgressSeries(visibleEntries.filter((entry) => entry.phaseSplits.length > 0)), [visibleEntries]);
  const phaseAo = useMemo(() => phaseStability(visibleEntries), [visibleEntries]);
  const pb = useMemo(() => { const values = visibleEntries.map(effectiveTime).filter((value): value is number => value !== null); return values.length ? Math.min(...values) : undefined; }, [visibleEntries]);
  const averages = useMemo(() => Object.fromEntries(AVERAGES.map((size) => [`ao${size}`, progress.at(-1)?.[`ao${size}`]])) as Record<`ao${typeof AVERAGES[number]}`, number | null | undefined>, [progress]);
  const selectedMetricDetail = useMemo(() => selectedMetric ? metricEvidence(visibleEntries, selectedMetric) : null, [selectedMetric, visibleEntries]);
  const latestSolution = useMemo(() => visibleEntries.find((entry) => entry.solution.trim()), [visibleEntries]);
  const latestEfficiency = useMemo(() => latestSolution ? solutionEfficiency(latestSolution) : null, [latestSolution]);
  const replayBaseState = replay ? initialStateFor(replay) : SOLVED_FAST_STATE;
  const replayText = replay?.solution ?? "";
  const replayTrace = useMemo(() => { if (!replayText.trim()) return []; try { return traceFastMoves(replayBaseState, replayText); } catch { return []; } }, [replayBaseState, replayText]);
  const replayCurrent = replayStep === 0 ? replayBaseState : replayTrace[replayStep - 1]?.state ?? SOLVED_FAST_STATE;
  const replayPrevious = replayStep > 0 ? replayTrace[replayStep - 1]?.previousState : undefined;
  const replayTps = replay && replay.elapsedMs > 0 ? replayTrace.length / (replay.elapsedMs / 1000) : 0;
  const phaseTps = useMemo(() => replay ? phaseTpsFromSolution(replay.solution) : [], [replay]);
  const allVisibleSelected = visibleEntries.length > 0 && visibleEntries.every((entry) => selectedIds.has(entry.id));
  const timerWcaProfile = wcaProfileQuery.data as { personalRecords?: TimerWcaRecord[] } | undefined;
  const eventWcaRecord = useMemo(() => timerWcaProfile?.personalRecords?.find((record) => record.eventId === eventId) ?? null, [eventId, timerWcaProfile]);
  const eventWcaRows = useMemo(() => wcaTimerComparison(eventEntries, eventWcaRecord ?? { singleCentiseconds: null, averageCentiseconds: null }, eventId), [eventEntries, eventId, eventWcaRecord]);

  useEffect(() => { if (!replayPlaying || replayStep >= replayTrace.length) return; const id = window.setTimeout(() => setReplayStep((value) => value + 1), Math.max(140, 560 / replaySpeed)); return () => window.clearTimeout(id); }, [replayPlaying, replayStep, replayTrace.length, replaySpeed]);
  useEffect(() => { if (replayStep >= replayTrace.length) setReplayPlaying(false); }, [replayStep, replayTrace.length]);
  // Timer quick controls are session-only overrides; long-lived defaults are owned by Settings.
  useEffect(() => { localStorage.setItem("cfop-metric-cubenets", showMetricCubeNets ? "on" : "off"); }, [showMetricCubeNets]);
  useEffect(() => { document.documentElement.dataset.speedSplit = spaceSplits ? "on" : "off"; return () => { delete document.documentElement.dataset.speedSplit; }; }, [spaceSplits]);
  useEffect(() => { if (!personalRecords.length) return; const id = window.setTimeout(() => setPersonalRecords([]), 5600); return () => window.clearTimeout(id); }, [personalRecords]);

  const copy = vi ? {
    title: "Timer Lab", back: "Về Studio", inspect: "INSPECTION · PRE-SOLVE", inspectDetail: "Chọn màu Cross và quan sát cube trước khi bắt đầu solve.", scramble: "SCRAMBLE", new: "Tạo case mới", copy: "COPY", soundOn: "Âm inspection: BẬT", soundOff: "Âm inspection: TẮT", highlightOn: "Hiện Cross: BẬT", highlightOff: "Hiện Cross: TẮT", splitOn: "Split input: BẬT", splitOff: "Split input: TẮT", splitDetail: "Khi solve chạy: Space, Enter hoặc chạm timer chốt Cross → F2L → OLL → PLL.", practice: "LUYỆN RIÊNG", full: "Full solve", crossPractice: "Cross", lastLayer: "Last Layer", case: "CASE", saved: "Đã lưu lượt vào nhật ký.", stats: "THÀNH TÍCH CÁ NHÂN", progress: "TIẾN ĐỘ AVERAGE", phaseProgress: "TIẾN ĐỘ TỪNG PHA", phaseEmpty: "CẦN LƯỢT CÓ SPEED SPLIT ĐỂ VẼ BIỂU ĐỒ PHA", targets: "MỤC TIÊU PHA · GIÂY", overTarget: "VƯỢT MỤC TIÊU", history: "NHẬT KÝ LƯỢT GIẢI", exportCsv: "Xuất CSV", exportJson: "Xuất JSON", importJson: "Nhập JSON", importError: "Không thể đọc backup JSON. Hãy chọn file lịch sử hợp lệ.", empty: "CHỜ LƯỢT ĐẦU TIÊN · GIỮ VÀ THẢ SPACE / ENTER HOẶC CHẠM TIMER", emptyFilter: "KHÔNG CÓ LƯỢT KHỚP BỘ LỌC HIỆN TẠI.", edit: "Chỉnh sửa lượt", base: "THỜI GIAN GỐC", penalty: "PHẠT", none: "Không phạt", note: "GHI CHÚ", tags: "TAG (phân cách bằng dấu phẩy)", solution: "SOLUTION THỰC TẾ", solutionHint: "Ghi đúng chuỗi move bạn đã thực hiện. Hệ thống chỉ lưu khi chuỗi đưa state của scramble về solved.", save: "Lưu solution", cancel: "Hủy", remove: "Xóa", deleteTitle: "Xóa lượt giải?", deleteDetail: "Lượt này sẽ bị xóa khỏi nhật ký và thống kê.", plusTwo: "+2", dnf: "DNF", pb: "PB", total: "LƯỢT", filter: "LỌC NHẬT KÝ", allTags: "Mọi tag", noteSearch: "Tìm ghi chú hoặc tag", matched: "lượt khớp", playback: "Phát lại solution thực tế", playbackTitle: "PHÁT LẠI SOLUTION THỰC TẾ", noSolution: "Lượt này chưa có solution thực tế đã lưu.", close: "Đóng", move: "NƯỚC XOAY", restart: "Phát lại từ đầu", speed: "TỐC ĐỘ", tps: "TPS", tpsByPhase: "TPS THEO PHA", tpsEmpty: "Lưu solution kèm thời gian từng pha để xem biểu đồ TPS.", splitTimes: "THỜI GIAN PHA", selectAll: "Chọn các lượt đang lọc", selected: "đã chọn", deleteSelected: "Xóa đã chọn", deleteManyTitle: "Xóa các lượt đã chọn?", deleteManyDetail: "Các lượt đang chọn sẽ bị xóa vĩnh viễn khỏi nhật ký và thống kê.", density: "MẬT ĐỘ HIỂN THỊ", standard: "Chuẩn", compact: "Gọn", recordTitle: "KỶ LỤC MỚI", recordClose: "Đóng thông báo kỷ lục" 
  } : {
    title: "Timer Lab", back: "Back to Studio", inspect: "INSPECTION · PRE-SOLVE", inspectDetail: "Choose the Cross color and inspect the cube before the solve.", scramble: "SCRAMBLE", new: "New case", copy: "COPY", soundOn: "Inspection sound: ON", soundOff: "Inspection sound: OFF", highlightOn: "Cross view: ON", highlightOff: "Cross view: OFF", splitOn: "Space split: ON", splitOff: "Space split: OFF", splitDetail: "During a solve, Space marks Cross → F2L → OLL → PLL.", practice: "PRACTICE", full: "Full solve", crossPractice: "Cross", lastLayer: "Last Layer", case: "CASE", saved: "Solve saved to the log.", stats: "PERSONAL METRICS", progress: "FILTERED AVERAGE PROGRESS", phaseProgress: "PHASE PROGRESS", phaseEmpty: "RECORD A SPEED SPLIT TO PLOT PHASE PROGRESS", targets: "PHASE TARGETS · SECONDS", overTarget: "OVER TARGET", chartEmpty: "WAITING FOR FILTERED DATA", history: "SOLVE LOG", exportCsv: "Export CSV", exportJson: "Export JSON", importJson: "Import JSON", importError: "The JSON backup could not be read. Choose a valid history file.", empty: "No solves saved yet.", emptyFilter: "No solves match the active filter.", edit: "Edit solve", base: "BASE TIME", penalty: "PENALTY", none: "No penalty", note: "NOTE", tags: "TAGS (comma separated)", solution: "OPTIONAL SOLUTION", solutionHint: "Use the move pad below or paste notation; add phase TPS metadata only when needed.", save: "Save changes", cancel: "Cancel", remove: "Delete", deleteTitle: "Delete this solve?", deleteDetail: "This solve will be removed from the log and metrics.", plusTwo: "+2", dnf: "DNF", pb: "PB", total: "SOLVES", filter: "FILTER LOG", allTags: "All tags", noteSearch: "Search notes or tags", matched: "matching solves", playback: "Playback", playbackTitle: "SOLUTION PLAYBACK", noSolution: "No solution saved for this solve.", close: "Close", move: "MOVE", restart: "Restart playback", speed: "SPEED", tps: "TPS", tpsByPhase: "TPS BY PHASE", tpsEmpty: "Save phase timings in the solution to see the TPS chart.", splitTimes: "PHASE SPLITS", selectAll: "Select filtered solves", selected: "selected", deleteSelected: "Delete selected", deleteManyTitle: "Delete selected solves?", deleteManyDetail: "The selected solves will be permanently removed from the log and metrics.", density: "DISPLAY DENSITY", standard: "Standard", compact: "Compact", recordTitle: "NEW PERSONAL RECORD", recordClose: "Dismiss record notice"
  };
  const activeSplitDetail = vi ? "Khi đồng hồ đang chạy, nhấn Space, Enter hoặc chạm vào đồng hồ để ghi các mốc bạn muốn theo dõi. Lần chạm cuối sẽ kết thúc lượt." : "While the timer runs, press Space, Enter, or touch it to record any milestones you want to follow. The last input finishes the attempt.";
  const analyticsCopy = vi ? { phaseAo: "AO5 / AO12 THEO PHA", presets: "CẤU HÌNH MỤC TIÊU", moves: "MOVES", efficiency: "HIỆU QUẢ SOLUTION", noSolution: "THÊM SOLUTION ĐỂ PHÂN TÍCH", applied: "ĐÃ ÁP DỤNG", set: "Áp dụng" } : { phaseAo: "PHASE AO5 / AO12", presets: "TARGET PRESETS", moves: "MOVES", efficiency: "SOLUTION EFFICIENCY", noSolution: "ADD A SOLUTION TO ANALYZE", applied: "APPLIED", set: "Apply" };

  const metric = (value: number | null | undefined) => value === undefined ? "--:--" : value === null ? "DNF" : formatSolveTime(value);
  const metricLabel = (key: TimerMetricKey) => key === "pb" ? copy.pb : key === "total" ? copy.total : key.toUpperCase();
  const copyMetricScramble = (entry: SolveHistoryEntry) => { const complete = () => { setCopiedScrambleId(entry.id); window.setTimeout(() => setCopiedScrambleId((current) => current === entry.id ? null : current), 1800); }; if (navigator.clipboard?.writeText) { void navigator.clipboard.writeText(entry.input).then(complete).catch(() => undefined); return; } const fallback = document.createElement("textarea"); fallback.value = entry.input; document.body.appendChild(fallback); fallback.select(); document.execCommand("copy"); fallback.remove(); complete(); };
  const recordLabel = (record: PersonalRecord) => record.key === "single" ? "PB SINGLE" : record.key.toUpperCase();
  const nextScramble = async (mode = practiceMode, clearSaved = true, selectedEvent = eventId) => { const request = ++scrambleRequest.current; setScrambleError(""); setTimerVersion((value) => value + 1); if (mode === "last-layer" && selectedEvent === DEFAULT_TIMER_EVENT) { const cases = [...OLL_CASES, ...PLL_CASES]; const nextCase = cases[Math.floor(Math.random() * cases.length)]; if (request === scrambleRequest.current) { setPracticeCase(nextCase); setScramble(nextCase.setup); setScrambleLoading(false); } } else { if (request === scrambleRequest.current) { setPracticeCase(null); setScramble(""); setScrambleLoading(true); } try { const next = await generateTimerScramble(selectedEvent); if (request === scrambleRequest.current) setScramble(next); } catch { if (request === scrambleRequest.current) setScrambleError(vi ? "Không thể tạo scramble cho event này. Hãy thử lại." : "Could not generate a scramble for this event. Please retry."); } finally { if (request === scrambleRequest.current) setScrambleLoading(false); } } if (clearSaved) setSaved(false); };
  const selectPracticeMode = (mode: PracticeMode) => { setPracticeMode(mode); nextScramble(mode); };
  const selectTimerEvent = (nextEventId: TimerEventId) => { setEventId(nextEventId); localStorage.setItem("cfop-timer-event", nextEventId); setPracticeMode("full"); setPracticeCase(null); setSelectedMetric(null); setLatestRecorded(null); setTagFilter("all"); setNoteQuery(""); void nextScramble("full", true, nextEventId); };
  const practiceSplitPhases: readonly SplitPhase[] = !isThreeByThree ? [] : practiceMode === "cross" ? ["Cross"] : practiceMode === "last-layer" ? [practiceCase?.kind ?? "OLL"] : SPEED_PHASES;
  const recordSolve = (completion: TimerCompletion) => { const tags = !isThreeByThree || practiceMode === "full" ? [] : [practiceMode === "cross" ? "practice:cross" : "practice:last-layer", ...(practiceCase ? [`case:${practiceCase.kind}-${practiceCase.id}`] : [])]; const item = addSolveHistory({ elapsedMs: completion.elapsedMs, inspectionMs: completion.inspectionMs, penalty: completion.automaticPenalty, phaseSplits: completion.phaseSplits, input: scramble, inputKind: "scramble", moves: 0, tags, eventId }); setPersonalRecords(detectPersonalRecords(eventEntries, item)); setEntries((previous) => [item, ...previous].slice(0, 500)); setLatestRecorded(item); setSaved(true); void nextScramble(practiceMode, false); };
  useEffect(() => { void nextScramble("full", false); }, []);
  const openEdit = (entry: SolveHistoryEntry) => { setEditing(entry); setEditSeconds((entry.elapsedMs / 1000).toFixed(2)); setEditPenalty(entry.penalty); setEditSolution(entry.solution); setEditNote(entry.note); setEditTags(entry.tags.join(", ")); setSolutionError(""); };
  const saveEdit = () => { if (!editing) return; const seconds = Number(editSeconds); if (!Number.isFinite(seconds) || seconds < 0) return; const validation = validateRecordedSolution(initialStateFor(editing), editSolution); if (!validation.valid && validation.error !== "empty") { setSolutionError(validation.error === "unfinished" ? (vi ? "Chuỗi move chưa đưa cube về trạng thái solved. Kiểm tra lại solution thực tế." : "This move sequence does not return the cube to solved. Check the recorded solution.") : (vi ? "Solution có notation không được hỗ trợ. Dùng các move Cube 3×3 chuẩn." : "The solution contains unsupported notation. Use standard 3×3 moves.")); return; } setEntries(updateSolveHistory(editing.id, { elapsedMs: Math.round(seconds * 1000), penalty: editPenalty, solution: validation.normalized, moves: validation.moves.length, note: editNote.trim(), tags: editTags.split(",").map((tag) => tag.trim()).filter(Boolean) })); setSolutionError(""); setEditing(null); };
  const applyPenalty = (entry: SolveHistoryEntry, penalty: SolvePenalty) => setEntries(updateSolveHistory(entry.id, { penalty: entry.penalty === penalty ? "none" : penalty }));
  const toggleSelection = (id: string) => setSelectedIds((current) => { const next = new Set(current); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  const selectVisible = () => setSelectedIds((current) => { const next = new Set(current); if (allVisibleSelected) visibleEntries.forEach((entry) => next.delete(entry.id)); else visibleEntries.forEach((entry) => next.add(entry.id)); return next; });
  const deleteSelected = () => { setEntries(deleteSolveHistoryMany(selectedIds)); setSelectedIds(new Set()); setBulkDeleteOpen(false); };
  const exportCsv = () => saveFile("cfop-timer-history.csv", "text/csv;charset=utf-8", [["timestamp", "base_time_ms", "inspection_ms", "penalty", "result", "phase_splits", "scramble", "solution", "notes", "tags"], ...entries.map((item) => [new Date(item.createdAt).toISOString(), item.elapsedMs, item.inspectionMs, item.penalty, formatSolveResult(item), splitSummary(item), item.input, item.solution, item.note, item.tags.join("|")])].map((row) => row.map(csvCell).join(",")).join("\n"));
  const exportJson = () => saveFile("cfop-timer-backup.json", "application/json", JSON.stringify(exportSolveHistory(), null, 2));
  const onImport = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; try { setEntries(importSolveHistory(JSON.parse(await file.text()))); setSelectedIds(new Set()); setImportError(""); } catch { setImportError(copy.importError); } finally { event.target.value = ""; } };
  const openReplay = (entry: SolveHistoryEntry) => { const validation = validateRecordedSolution(initialStateFor(entry), entry.solution); if (!validation.valid || !validation.moves.length) return; setReplay({ ...entry, solution: validation.normalized }); setReplayStep(0); setReplayPlaying(false); setReplaySpeed(1); };

  return <div><div className="container pb-5"><h1 className="visually-hidden">{labTab === "study" ? (vi ? "Study" : "Study") : (vi ? "Timer" : "Timer")}</h1>
    {labTab === "study" ? <LastLayerStudyLab language={language} /> : <>
    <section className="row g-4">
      <section className="col-12 col-xl-8"><div className="card"><div className="card-body"><div className="row g-2 align-items-end mb-3"><label className="col-12 col-sm"><span className="form-label small text-body-secondary mb-1">{vi ? "Loại khối" : "Puzzle"}</span><select className="form-select" value={eventId} onChange={(event) => selectTimerEvent(event.target.value as TimerEventId)}>{TIMER_EVENTS.map((event) => <option key={event.id} value={event.id}>{timerEventLabel(event.id, language)}</option>)}</select></label><div className="col-auto"><div className="d-flex align-items-center gap-2"><button type="button" className="btn btn-outline-secondary btn-sm" disabled={scrambleLoading} onClick={() => void nextScramble()} title={copy.new} aria-label={copy.new}><Dices className="fs-6" /></button><button type="button" className="btn btn-outline-secondary btn-sm" disabled={!scramble || scrambleLoading} onClick={() => navigator.clipboard?.writeText(scramble)} title={copy.copy} aria-label={copy.copy}><ClipboardCheck className="fs-6" /></button></div></div></div><p className="fs-4 fw-bold text-break mb-2" aria-live="polite">{scrambleLoading ? (vi ? `Đang tạo scramble ${eventLabel}…` : `Generating ${eventLabel} scramble…`) : scramble}</p>{scrambleError ? <div className="alert alert-warning small mb-3">{scrambleError}</div> : null}
        <div className="row g-3 mt-1 align-items-stretch"><div className="col-12 col-lg-7">{scrambleLoading ? <div className="card card-body placeholder-glow text-center"><span className="placeholder col-8 mx-auto" /><span className="placeholder col-5 mx-auto mt-3" /></div> : <SolveTimer key={timerVersion} onComplete={recordSolve} soundEnabled={inspectionSound} splitEnabled={isThreeByThree && (spaceSplits || practiceMode !== "full")} splitPhases={practiceSplitPhases} />}{isThreeByThree && (spaceSplits || practiceMode !== "full") && <div className="alert alert-info small mt-3 mb-0">{activeSplitDetail}</div>}{saved && <div className="alert alert-success small mt-3 mb-0">{copy.saved}</div>}{isThreeByThree && saved && latestRecorded && !latestRecorded.solution.trim() && <div className="alert alert-secondary small mt-3 mb-0 d-flex flex-column flex-sm-row align-items-sm-center justify-content-between gap-2"><span>{vi ? "Timer không thể tự biết các nước bạn đã xoay; hãy nhập chuỗi move để phát lại chính xác." : "The timer cannot observe physical turns; add the moves for an exact replay."}</span><button type="button" onClick={() => openEdit(latestRecorded)} className="btn btn-outline-primary btn-sm flex-shrink-0">{vi ? "Nhập solution" : "Add solution"}</button></div>}</div><div className="col-12 col-lg-5">{isThreeByThree ? <Cube3DGuide state={state} step={0} crossColor={inspectionColor} inspection alignCross highlightCross={crossHighlight} /> : timerPreviewPuzzleId(eventId) && scramble && !scrambleLoading ? <PuzzleScramblePreview eventId={eventId} scramble={scramble} language={language} /> : <div className="card card-body h-100 d-flex justify-content-center text-center"><i className="bi bi-stopwatch fs-1 text-body-secondary mb-3" aria-hidden="true" /><p className="fw-semibold mb-1">{eventLabel}</p><p className="small text-body-secondary mb-0">{vi ? "Timer và scramble được tách riêng theo event." : "Timer and scrambles are separated by event."}</p></div>}</div></div>
        {isThreeByThree && practiceCase && <div className="alert alert-secondary small mt-3 mb-0">{copy.case} · {practiceCase.kind} {practiceCase.id} · {practiceCase.group}</div>}
      </div></div></section>
      <aside className="col-12 col-xl-4" aria-label={copy.stats}><div className="card"><div className="card-body"><div className="d-flex align-items-center justify-content-between gap-3"><p className="h6 mb-0">{copy.stats}</p><span className="small text-body-secondary">{visibleEntries.length} {copy.total}</span></div><div className="row g-2 mt-1"><div className="col-12 col-sm-6"><MetricButton label={copy.pb} value={metric(pb)} enabled={pb !== undefined} onClick={() => setSelectedMetric("pb")} /></div><div className="col-12 col-sm-6"><MetricButton label="AO5" value={metric(averages.ao5)} enabled={averages.ao5 !== undefined} onClick={() => setSelectedMetric("ao5")} /></div><div className="col-12 col-sm-6"><MetricButton label="AO12" value={metric(averages.ao12)} enabled={averages.ao12 !== undefined} onClick={() => setSelectedMetric("ao12")} /></div><div className="col-12 col-sm-6"><MetricButton label="AO50" value={metric(averages.ao50)} enabled={averages.ao50 !== undefined} onClick={() => setSelectedMetric("ao50")} /></div><div className="col-12 col-sm-6"><MetricButton label="AO100" value={metric(averages.ao100)} enabled={averages.ao100 !== undefined} onClick={() => setSelectedMetric("ao100")} /></div><div className="col-12 col-sm-6"><MetricButton label={copy.total} value={String(visibleEntries.length)} enabled={visibleEntries.length > 0} onClick={() => setSelectedMetric("total")} /></div></div></div></div></aside>
      {personalRecords.length > 0 && <aside className="timer-record-celebration" role="status" aria-live="polite"><div className="timer-record-spark" aria-hidden="true" /><div className="timer-record-copy"><span className="timer-record-mark"><Trophy className="h-4 w-4" /></span><div><p>{copy.recordTitle}</p><div className="timer-record-values">{personalRecords.map((record) => <span key={record.key}><b>{recordLabel(record)}</b> {formatSolveTime(record.value)}</span>)}</div></div></div><button type="button" onClick={() => setPersonalRecords([])} aria-label={copy.recordClose}><X className="h-3.5 w-3.5" /></button></aside>}

      <section className="col-12"><EventProgressCard eventLabel={eventLabel} entries={eventEntries} progress={progress} language={language} /></section>
      <section className="col-12"><EventWcaComparisonCard eventId={eventId} eventLabel={eventLabel} rows={eventWcaRows} hasWcaId={Boolean(accountQuery.data?.wcaId)} loading={wcaProfileQuery.isLoading} unavailable={wcaProfileQuery.isError} hasRecord={Boolean(eventWcaRecord)} language={language} /></section>

      <details className="d-none" aria-hidden="true"><summary>{vi ? "Mở phân tích & mục tiêu" : "Open analytics & targets"}</summary><div className="mt-5 space-y-7"><section className="row g-4"><div className="col-12 col-xl-4 card card-body"><p className="h6">{copy.stats}</p><div className="mt-4 grid grid-cols-3 gap-2"><Metric label={copy.pb} value={metric(pb)} /><Metric label="AO5" value={metric(averages.ao5)} /><Metric label="AO12" value={metric(averages.ao12)} /><Metric label="AO50" value={metric(averages.ao50)} /><Metric label="AO100" value={metric(averages.ao100)} /><Metric label={copy.total} value={String(visibleEntries.length)} /></div></div><div className="col-12 col-xl-8 card card-body"><p className="h6">{copy.progress}</p>{visibleEntries.length ? <div className="mt-4 h-72"><ResponsiveContainer width="100%" height="100%"><LineChart data={progress}><XAxis dataKey="solve" type="number" axisLine={false} tickLine={false} /><YAxis tickFormatter={(value) => `${(Number(value) / 1000).toFixed(0)}s`} axisLine={false} tickLine={false} width={46} /><Tooltip formatter={(value) => [value == null ? "DNF" : `${(Number(value) / 1000).toFixed(2)}s`]} /><Line type="monotone" dataKey="ao5" stroke="#0d6efd" strokeWidth={3} dot={false} connectNulls name="Ao5" /><Line type="monotone" dataKey="ao12" stroke="#6c757d" strokeWidth={2} dot={false} connectNulls name="Ao12" /><Line type="monotone" dataKey="ao50" stroke="#dc3545" strokeWidth={2} strokeDasharray="5 3" dot={false} connectNulls name="Ao50" /><Line type="monotone" dataKey="ao100" stroke="#0dcaf0" strokeWidth={2} strokeDasharray="2 4" dot={false} connectNulls name="Ao100" /></LineChart></ResponsiveContainer></div> : <div className="alert alert-secondary mt-4">{copy.chartEmpty}</div>}</div></section>

      <section className="row g-4 mt-3"><div className="col-12 col-lg-4"><div className="card h-100"><div className="card-body"><h2 className="h6">{copy.targets}</h2>{SPEED_PHASES.map((phase) => <label key={phase} className="form-label d-flex align-items-center justify-content-between border-bottom py-2 mb-0"><span>{phase}</span><div className="input-group input-group-sm" style={{ width: "8rem" }}><input type="number" min="0.1" max="120" step="0.1" value={phaseTargets[phase]} onChange={(event) => { const next = Number(event.target.value); if (Number.isFinite(next) && next > 0) setPhaseTargets((current) => ({ ...current, [phase]: next })); }} className="form-control text-end" /><span className="input-group-text">s</span></div></label>)}</div></div></div><div className="col-12 col-lg-8"><div className="card h-100"><div className="card-body"><div className="d-flex justify-content-between align-items-center"><h2 className="h6 mb-0">{copy.phaseProgress}</h2><span className="small text-body-secondary">{phaseProgress.length} {copy.matched}</span></div>{phaseProgress.length ? <div style={{ height: "18rem" }} className="mt-3"><ResponsiveContainer width="100%" height="100%"><LineChart data={phaseProgress}><XAxis dataKey="solve" axisLine={false} tickLine={false} /><YAxis tickFormatter={(value) => `${Number(value).toFixed(0)}s`} axisLine={false} tickLine={false} width={42} /><Tooltip formatter={(value) => [`${(Number(value) / 1000).toFixed(2)}s`, ""]} /><Line type="monotone" dataKey="Cross" stroke="#0d6efd" strokeWidth={3} dot={{ r: 2 }} connectNulls /><Line type="monotone" dataKey="F2L" stroke="#fd7e14" strokeWidth={2} dot={{ r: 2 }} connectNulls /><Line type="monotone" dataKey="OLL" stroke="#0dcaf0" strokeWidth={2} dot={{ r: 2 }} connectNulls /><Line type="monotone" dataKey="PLL" stroke="#dc3545" strokeWidth={2} dot={{ r: 2 }} connectNulls /></LineChart></ResponsiveContainer></div> : <div className="alert alert-secondary text-center mt-3 mb-0">{copy.phaseEmpty}</div>}</div></div></div></section>

      <section className="row g-4 mt-3"><div className="col-12 col-lg-4"><div className="card h-100"><div className="card-body"><h2 className="h6">{analyticsCopy.presets}</h2><div className="d-grid gap-2 mt-3">{(Object.entries(TARGET_PRESETS) as [keyof typeof TARGET_PRESETS, Record<SplitPhase, number>][]).map(([name, targets]) => { const active = SPEED_PHASES.every((phase) => phaseTargets[phase] === targets[phase]); return <button key={name} onClick={() => setPhaseTargets({ ...targets })} className={active ? "btn btn-primary" : "btn btn-outline-secondary"}>{name} · {active ? analyticsCopy.applied : analyticsCopy.set}</button>; })}</div></div></div></div><div className="col-12 col-lg-8"><div className="card h-100"><div className="card-body"><div className="d-flex justify-content-between align-items-center"><h2 className="h6 mb-0">{analyticsCopy.phaseAo}</h2><span className="small text-body-secondary">{visibleEntries.length} {copy.matched}</span></div><div className="row g-3 mt-1">{SPEED_PHASES.map((phase) => <div key={phase} className="col-12 col-md-6"><div className="card bg-body-tertiary h-100"><div className="card-body"><div className="d-flex justify-content-between"><strong>{phase}</strong><span className="small text-body-secondary">{phaseAo[phase].count}</span></div><div className="row mt-2"><div className="col-6"><small className="text-body-secondary d-block">AO5</small><strong>{phaseAo[phase].ao5 === undefined ? "—" : formatSolveTime(phaseAo[phase].ao5)}</strong></div><div className="col-6"><small className="text-body-secondary d-block">AO12</small><strong>{phaseAo[phase].ao12 === undefined ? "—" : formatSolveTime(phaseAo[phase].ao12)}</strong></div></div></div></div></div>)}</div></div></div></div></section>

      <section className="card mt-4"><div className="card-body"><div className="d-flex flex-wrap justify-content-between gap-2"><h2 className="h6 mb-0">{analyticsCopy.efficiency}</h2>{latestSolution && <span className="small text-body-secondary">{new Date(latestSolution.createdAt).toLocaleDateString(vi ? "vi-VN" : "en-US")}</span>}</div>{latestEfficiency ? <div className="row g-3 mt-1"><div className="col-12 col-md-6"><MetricDark label={analyticsCopy.moves} value={String(latestEfficiency.moves)} /></div><div className="col-12 col-md-6"><MetricDark label={copy.tps} value={latestEfficiency.tps.toFixed(2)} /></div><div className="col-12"><MetricDark label="RATING" value={latestEfficiency.label} /></div></div> : <div className="alert alert-secondary mt-3 mb-0">{analyticsCopy.noSolution}</div>}</div></section>

      </div></details>
      <section className="col-12"><div className="card"><div className="card-header d-flex flex-wrap align-items-center justify-content-between gap-2"><div><h2 className="h5 mb-0">{vi ? `Solve ${eventLabel} gần nhất` : `Recent ${eventLabel} solves`}</h2><small className="text-body-secondary">{vi ? "Chỉnh sửa, export và quản lý lịch sử nằm trong History." : "Edit, export, and full history management live in History."}</small></div><Link href="/history" className="btn btn-outline-secondary btn-sm">{vi ? "Mở History" : "Open History"}</Link></div><div className="card-body">{eventEntries.length ? <div className="list-group list-group-flush">{eventEntries.slice(0, 5).map((item) => <RecentTimerSolve key={item.id} item={item} vi={vi} />)}</div> : <div className="alert alert-info mb-0">{vi ? `Chưa có solve ${eventLabel}.` : `No ${eventLabel} solves yet.`}</div>}</div></div></section>
    </section>

    <Dialog open={Boolean(selectedMetric)} onOpenChange={(open) => !open && setSelectedMetric(null)}><DialogContent><DialogHeader><div><DialogTitle>{vi ? "Chi tiết thành tích" : "Metric detail"} · {selectedMetric ? metricLabel(selectedMetric) : "—"}</DialogTitle><DialogDescription>{selectedMetricDetail?.value === undefined ? (vi ? "Chưa đủ lượt hợp lệ để tạo chỉ số này." : "Not enough valid solves to form this metric.") : selectedMetric === "total" ? `${selectedMetricDetail.entries.length} ${copy.total.toLowerCase()}` : metric(selectedMetricDetail?.value)}</DialogDescription></div></DialogHeader><div className="modal-body"><div className="d-flex flex-wrap justify-content-between align-items-center gap-2"><div className="btn-group btn-group-sm" role="group">{isThreeByThree && <button type="button" onClick={() => setShowMetricCubeNets((value) => !value)} aria-label={showMetricCubeNets ? (vi ? "Ẩn CubeNet" : "Hide CubeNet") : (vi ? "Hiện CubeNet" : "Show CubeNet")} className="btn btn-outline-secondary">{showMetricCubeNets ? <EyeOff className="fs-6" /> : <Eye className="fs-6" />}</button>}{isThreeByThree && selectedMetric === "ao5" && selectedMetricDetail && <button type="button" onClick={() => exportAo5Image(selectedMetricDetail.entries, selectedMetricDetail.exclusions, selectedMetricDetail.value, vi)} aria-label={vi ? "Xuất ảnh Ao5" : "Export Ao5 PNG"} className="btn btn-primary"><ImageDown className="fs-6" /></button>}</div><span className="small text-body-secondary">{selectedMetricDetail?.entries.length ?? 0} {vi ? "lượt" : "solves"}</span></div>{selectedMetric?.startsWith("ao") && <div className="d-flex flex-wrap gap-1 mt-3"><span className="badge text-bg-success">{vi ? "Best bị loại" : "Best discarded"}</span><span className="badge text-bg-danger">{vi ? "Worst bị loại" : "Worst discarded"}</span></div>}{selectedMetricDetail?.entries.length ? <div className="list-group mt-3">{selectedMetricDetail.entries.map((entry) => <MetricDetailCard key={entry.id} entry={entry} exclusion={selectedMetricDetail.exclusions[entry.id]} vi={vi} showCubeNet={showMetricCubeNets} copied={copiedScrambleId === entry.id} onCopy={copyMetricScramble} onExpand={setExpandedMetricCube} onReplay={openReplay} />)}</div> : <div className="alert alert-secondary mt-3 mb-0">{vi ? "Chưa có scramble để hiển thị." : "No scrambles are available for this metric."}</div>}</div><DialogFooter><button type="button" onClick={() => setSelectedMetric(null)} className="btn btn-outline-secondary">{copy.close}</button></DialogFooter></DialogContent></Dialog>
    <Dialog open={Boolean(expandedMetricCube)} onOpenChange={(open) => !open && setExpandedMetricCube(null)}><DialogContent><DialogHeader><div><DialogTitle>CubeNet · Scramble</DialogTitle><DialogDescription><span className="font-monospace text-break">{expandedMetricCube?.input}</span></DialogDescription></div></DialogHeader><div className="modal-body d-flex justify-content-center">{expandedMetricCube && <CubeNet state={safeScrambleState(expandedMetricCube.input)} />}</div><DialogFooter><button type="button" onClick={() => setExpandedMetricCube(null)} className="btn btn-outline-secondary">{copy.close}</button></DialogFooter></DialogContent></Dialog>
    <Dialog open={Boolean(editing)} onOpenChange={(open) => !open && setEditing(null)}><DialogContent><DialogHeader><div><DialogTitle>{copy.edit}</DialogTitle><DialogDescription><span className="font-monospace text-break">{editing?.input}</span></DialogDescription></div></DialogHeader><div className="modal-body"><div className="row g-3"><label className="col-12 col-md-6"><span className="form-label">{copy.base}</span><input type="number" min="0" step="0.01" value={editSeconds} onChange={(event) => setEditSeconds(event.target.value)} className="form-control" /></label><label className="col-12 col-md-6"><span className="form-label">{copy.penalty}</span><select value={editPenalty} onChange={(event) => setEditPenalty(event.target.value as SolvePenalty)} className="form-select"><option value="none">{copy.none}</option><option value="+2">{copy.plusTwo}</option><option value="DNF">{copy.dnf}</option></select></label><div className="col-12"><MoveComposer value={editSolution} onChange={(value) => { setEditSolution(value); if (solutionError) setSolutionError(""); }} label={copy.solution} pasteLabel={copy.solutionHint} /></div>{solutionError && <div className="col-12"><div role="alert" className="alert alert-danger mb-0">{solutionError}</div></div>}<label className="col-12"><span className="form-label">{copy.note}</span><textarea value={editNote} onChange={(event) => setEditNote(event.target.value)} className="form-control" rows={3} /></label><label className="col-12"><span className="form-label">{copy.tags}</span><input value={editTags} onChange={(event) => setEditTags(event.target.value)} className="form-control" /></label></div></div><DialogFooter><button type="button" onClick={() => setEditing(null)} className="btn btn-outline-secondary">{copy.cancel}</button><button type="button" onClick={saveEdit} className="btn btn-primary">{copy.save}</button></DialogFooter></DialogContent></Dialog>

    <Dialog open={Boolean(replay)} onOpenChange={(open) => { if (!open) { setReplay(null); setReplayPlaying(false); setReplayStep(0); } }}><DialogContent><DialogHeader><div><DialogTitle>{copy.playbackTitle}</DialogTitle><DialogDescription><span className="font-monospace text-break">{replayText}</span></DialogDescription></div></DialogHeader><div className="modal-body">{replayTrace.length ? <div className="row g-3"><div className="col-12 col-lg-7"><Cube3DGuide state={replayCurrent} previousState={replayPrevious} move={replayStep ? replayTrace[replayStep - 1]?.move : undefined} step={replayStep} crossColor={inspectionColor} alignCross /></div><div className="col-12 col-lg-5"><div className="card h-100"><div className="card-body"><p className="small text-uppercase fw-semibold text-body-secondary mb-1">{copy.move}</p><p className="display-6 font-monospace fw-bold">{replayStep ? replayTrace[replayStep - 1]?.move : "—"}</p><p className="small text-body-secondary">{replayStep} / {replayTrace.length} · {copy.tps} {replayTps.toFixed(2)}</p><label className="form-label small mt-3">{copy.speed} {replaySpeed.toFixed(2)}×</label><input type="range" min="0.5" max="2" step="0.25" value={replaySpeed} onChange={(event) => setReplaySpeed(Number(event.target.value))} className="form-range" />{replay?.phaseSplits.length ? <div className="mt-3"><p className="small fw-semibold mb-1">{copy.splitTimes}</p><div className="row g-1">{replay.phaseSplits.map((split) => <div key={split.phase} className="col-6"><span className="small text-body-secondary">{split.phase} </span><strong className="small">{(split.elapsedMs / 1000).toFixed(2)}s</strong></div>)}</div></div> : null}{phaseTps.length ? <div className="mt-3"><p className="small fw-semibold mb-1">{copy.tpsByPhase}</p><div style={{ height: "10rem" }}><ResponsiveContainer width="100%" height="100%"><BarChart data={phaseTps}><XAxis dataKey="phase" axisLine={false} tickLine={false} tick={{ fontSize: 9 }} /><YAxis axisLine={false} tickLine={false} tick={{ fontSize: 9 }} width={24} /><Tooltip formatter={(value) => [`${Number(value).toFixed(2)} TPS`, copy.tps]} /><Bar dataKey="tps" fill="#0d6efd" radius={[2, 2, 0, 0]} /></BarChart></ResponsiveContainer></div></div> : <div className="alert alert-secondary small py-2 mt-3 mb-0">{copy.tpsEmpty}</div>}<div className="btn-group w-100 mt-3" role="group"><button type="button" onClick={() => setReplayStep((value) => Math.max(0, value - 1))} className="btn btn-outline-secondary" aria-label={vi ? "Nước trước" : "Previous move"}>←</button><button type="button" onClick={() => setReplayPlaying((value) => !value)} className="btn btn-primary">{replayPlaying ? <Pause className="fs-6 me-1" /> : <Play className="fs-6 me-1" />}{replayPlaying ? "Pause" : "Play"}</button><button type="button" onClick={() => setReplayStep((value) => Math.min(replayTrace.length, value + 1))} className="btn btn-outline-secondary" aria-label={vi ? "Nước sau" : "Next move"}>→</button></div><button type="button" onClick={() => { setReplayStep(0); setReplayPlaying(false); }} className="btn btn-outline-secondary w-100 mt-2 d-inline-flex align-items-center justify-content-center gap-1"><RotateCcw className="fs-6" />{copy.restart}</button></div></div></div></div> : <div className="alert alert-secondary mb-0">{copy.noSolution}</div>}</div><DialogFooter><button type="button" onClick={() => setReplay(null)} className="btn btn-outline-secondary">{copy.close}</button></DialogFooter></DialogContent></Dialog>

    <Dialog open={Boolean(deleteTarget)} onOpenChange={(open) => !open && setDeleteTarget(null)}><DialogContent><DialogHeader><div><DialogTitle>{copy.deleteTitle}</DialogTitle><DialogDescription>{copy.deleteDetail}</DialogDescription></div></DialogHeader><DialogFooter><button type="button" className="btn btn-outline-secondary" onClick={() => setDeleteTarget(null)}>{copy.cancel}</button><button type="button" className="btn btn-danger" onClick={() => { if (deleteTarget) setEntries(deleteSolveHistory(deleteTarget.id)); setDeleteTarget(null); }}>{copy.remove}</button></DialogFooter></DialogContent></Dialog>
    <Dialog open={bulkDeleteOpen} onOpenChange={setBulkDeleteOpen}><DialogContent><DialogHeader><div><DialogTitle>{copy.deleteManyTitle}</DialogTitle><DialogDescription>{copy.deleteManyDetail}</DialogDescription></div></DialogHeader><DialogFooter><button type="button" className="btn btn-outline-secondary" onClick={() => setBulkDeleteOpen(false)}>{copy.cancel}</button><button type="button" className="btn btn-danger" onClick={deleteSelected}>{copy.deleteSelected}</button></DialogFooter></DialogContent></Dialog>
    </>}
  </div></div>;
}

function EventProgressCard({ eventLabel, entries, progress, language }: { eventLabel: string; entries: SolveHistoryEntry[]; progress: ReturnType<typeof progressSeries>; language: "vi" | "en" }) {
  const vi = language === "vi";
  return <div className="card h-100"><div className="card-body"><div className="d-flex flex-wrap align-items-center justify-content-between gap-2"><div><h2 className="h6 mb-1">{vi ? `Tiến bộ ${eventLabel}` : `${eventLabel} progress`}</h2><p className="small text-body-secondary mb-0">{vi ? "Single, Ao5 và Ao12 chỉ dùng solve của loại khối đang chọn." : "Single, Ao5, and Ao12 use only solves for the selected puzzle."}</p></div><span className="small text-body-secondary">{entries.length} {vi ? "lượt" : "solves"}</span></div>{entries.length ? <div style={{ height: "17rem" }} className="mt-3"><ResponsiveContainer width="100%" height="100%"><LineChart data={progress}><XAxis dataKey="solve" axisLine={false} tickLine={false} /><YAxis tickFormatter={(value) => `${(Number(value) / 1000).toFixed(0)}s`} axisLine={false} tickLine={false} width={42} /><Tooltip formatter={(value) => [value == null ? "DNF" : formatSolveTime(Number(value)), ""]} /><Line type="monotone" dataKey="single" stroke="#6c757d" strokeWidth={1.5} dot={{ r: 2 }} connectNulls name="Single" /><Line type="monotone" dataKey="ao5" stroke="#0d6efd" strokeWidth={3} dot={false} connectNulls name="Ao5" /><Line type="monotone" dataKey="ao12" stroke="#0dcaf0" strokeWidth={2} dot={false} connectNulls name="Ao12" /></LineChart></ResponsiveContainer></div> : <div className="alert alert-info small mt-3 mb-0">{vi ? `Hoàn thành solve ${eventLabel} đầu tiên để bắt đầu biểu đồ.` : `Complete a ${eventLabel} solve to start the chart.`}</div>}</div></div>;
}

function wcaDeltaMessage(deltaMs: number | null, language: "vi" | "en") {
  if (deltaMs === null) return language === "vi" ? "Cần dữ liệu ở cả hai nguồn" : "Both sources need data";
  if (deltaMs === 0) return language === "vi" ? "Bằng nhau" : "Equal";
  const difference = formatSolveTime(Math.abs(deltaMs));
  if (language === "vi") return deltaMs < 0 ? `Timer nhanh hơn ${difference}` : `WCA nhanh hơn ${difference}`;
  return deltaMs < 0 ? `Timer faster by ${difference}` : `WCA faster by ${difference}`;
}

function EventWcaComparisonCard({ eventId, eventLabel, rows, hasWcaId, loading, unavailable, hasRecord, language }: { eventId: TimerEventId; eventLabel: string; rows: WcaTimerComparisonRow[]; hasWcaId: boolean; loading: boolean; unavailable: boolean; hasRecord: boolean; language: "vi" | "en" }) {
  const vi = language === "vi";
  return <div className="card"><div className="card-body"><div className="d-flex flex-wrap align-items-center justify-content-between gap-2"><div><h2 className="h6 mb-1">{vi ? `PB ${eventLabel} · Timer và WCA` : `${eventLabel} PB · Timer vs WCA`}</h2><p className="small text-body-secondary mb-0">{vi ? "So sánh PB Timer với personal record WCA của đúng event này." : "Compares the Timer PB with the WCA personal record for this exact event."}</p></div>{hasWcaId ? <Link href="/profile" className="btn btn-outline-secondary btn-sm">{vi ? "Hồ sơ WCA" : "WCA profile"}</Link> : <Link href="/profile" className="btn btn-outline-secondary btn-sm">{vi ? "Liên kết WCA ID" : "Link WCA ID"}</Link>}</div>{!hasWcaId ? <div className="alert alert-secondary small mt-3 mb-0">{vi ? "Liên kết WCA ID trong Hồ sơ để xem single/average chính thức cạnh PB Timer." : "Link a WCA ID in Profile to see official single/average beside the Timer PB."}</div> : loading ? <div className="placeholder-glow mt-3"><span className="placeholder col-8" /><span className="placeholder col-5 d-block mt-2" /></div> : unavailable ? <div className="alert alert-warning small mt-3 mb-0">{vi ? "Chưa thể tải dữ liệu WCA lúc này. Thành tích Timer vẫn được giữ nguyên." : "WCA data is unavailable right now. Timer records remain unchanged."}</div> : <><div className="table-responsive mt-3"><table className="table table-sm align-middle mb-0"><thead><tr><th scope="col">{vi ? "Chỉ số" : "Metric"}</th><th scope="col">Timer</th><th scope="col">WCA</th><th scope="col">{vi ? "Chênh lệch" : "Difference"}</th></tr></thead><tbody>{rows.map((row) => <tr key={row.key}><th scope="row">{row.label}</th><td>{row.timerMs === null ? "—" : formatSolveTime(row.timerMs)}</td><td>{row.wcaMs === null ? "—" : formatSolveTime(row.wcaMs)}</td><td className={row.deltaMs === null ? "text-body-secondary" : row.deltaMs < 0 ? "text-success" : row.deltaMs > 0 ? "text-primary" : "text-body-secondary"}>{wcaDeltaMessage(row.deltaMs, language)}</td></tr>)}</tbody></table></div>{!hasRecord ? <p className="small text-body-secondary mt-2 mb-0">{vi ? `WCA ID này chưa có record ${eventLabel}; bảng vẫn giữ PB Timer để bạn theo dõi.` : `This WCA ID has no ${eventLabel} record yet; the Timer PB remains available.`}</p> : <p className="small text-body-secondary mt-2 mb-0">{vi ? "Ao5 Timer là PB Ao5 nội bộ; WCA average chỉ là thành tích chính thức tham khảo." : "Timer Ao5 is an internal PB; WCA average is the official reference result."}</p>}</>}</div></div>;
}

function RecentTimerSolve({ item, vi }: { item: SolveHistoryEntry; vi: boolean }) { return <article className="list-group-item d-flex flex-wrap align-items-center justify-content-between gap-3"><div><strong className={item.penalty === "DNF" ? "text-danger" : ""}>{formatSolveResult(item)}</strong><small className="d-block text-body-secondary">{new Date(item.createdAt).toLocaleString(vi ? "vi-VN" : "en-US")}{item.tags.length ? ` · ${item.tags.join(", ")}` : ""}</small></div><span className="font-monospace small text-break flex-grow-1">{item.input}</span></article>; }
function Metric({ label, value }: { label: string; value: string }) { return <div className="card bg-body-tertiary"><div className="card-body"><small className="text-body-secondary">{label}</small><strong className="fs-5 d-block">{value}</strong></div></div>; }
function MetricDetailCard({ entry, exclusion, vi, showCubeNet, copied, onCopy, onExpand, onReplay }: { entry: SolveHistoryEntry; exclusion?: "best" | "worst"; vi: boolean; showCubeNet: boolean; copied: boolean; onCopy: (entry: SolveHistoryEntry) => void; onExpand: (entry: SolveHistoryEntry) => void; onReplay: (entry: SolveHistoryEntry) => void }) { const isThreeByThree = normalizeTimerEventId(entry.eventId) === DEFAULT_TIMER_EVENT; const state = useMemo(() => safeScrambleState(entry.input), [entry.input]); const solution = useMemo(() => isThreeByThree ? validateRecordedSolution(initialStateFor(entry), entry.solution) : null, [entry, isThreeByThree]); const canReplay = Boolean(solution?.valid && solution.moves.length > 0); return <article className="list-group-item"><div className="row g-3 align-items-center">{isThreeByThree && showCubeNet && <div className="col-12 col-md-auto"><button type="button" onClick={() => onExpand(entry)} aria-label={vi ? "Phóng to CubeNet" : "Enlarge CubeNet"} className="btn btn-outline-secondary btn-sm"><CubeNet state={state} compact /></button></div>}<div className="col"><div className="d-flex flex-wrap align-items-start justify-content-between gap-2"><div><strong className="fs-5">{formatSolveResult(entry)}</strong><small className="d-block text-body-secondary">{new Date(entry.createdAt).toLocaleString(vi ? "vi-VN" : "en-US")}</small></div><div className="d-flex flex-wrap gap-1">{entry.penalty !== "none" && <span className={entry.penalty === "DNF" ? "badge text-bg-danger" : "badge text-bg-warning"}>{entry.penalty}</span>}{exclusion && <span className={exclusion === "best" ? "badge text-bg-success" : "badge text-bg-danger"}>{exclusion === "best" ? (vi ? "Best bị loại" : "Best discarded") : (vi ? "Worst bị loại" : "Worst discarded")}</span>}</div></div><p className="font-monospace text-break mt-2 mb-2">{entry.input}</p><div className="d-flex flex-wrap align-items-center gap-2"><button type="button" onClick={() => onCopy(entry)} aria-label={copied ? (vi ? "Đã chép scramble" : "Scramble copied") : (vi ? "Sao chép scramble" : "Copy scramble")} className="btn btn-outline-secondary btn-sm"><ClipboardCheck className="fs-5" /></button>{canReplay ? <button type="button" onClick={() => onReplay(entry)} aria-label={vi ? "Phát solution" : "Play solution"} className="btn btn-outline-secondary btn-sm"><Play className="fs-5" /></button> : <span className="small text-body-secondary">{isThreeByThree ? (vi ? "Chưa lưu solution thực tế" : "No saved solution") : (vi ? "Replay chỉ hỗ trợ 3×3" : "Replay is available for 3×3 only")}</span>}</div></div></div></article>; }
function MetricButton({ label, value, enabled, onClick }: { label: string; value: string; enabled: boolean; onClick: () => void }) { return <button type="button" disabled={!enabled} onClick={onClick} className="btn btn-outline-secondary w-100 text-start h-100"><small className="text-body-secondary d-block">{label}</small><strong className="fs-5">{value}</strong></button>; }
function MetricDark({ label, value }: { label: string; value: string }) { return <div className="card bg-dark text-white"><div className="card-body"><small className="text-white-50">{label}</small><strong className="fs-5 d-block">{value}</strong></div></div>; }
function TimerHistoryRow({ item, vi, phaseTargets, selected, onSelect, onPenalty, onReplay, onEdit, onDelete, labels }: { item: SolveHistoryEntry; vi: boolean; phaseTargets: Record<SplitPhase, number>; selected: boolean; onSelect: () => void; onPenalty: (item: SolveHistoryEntry, penalty: SolvePenalty) => void; onReplay: (item: SolveHistoryEntry) => void; onEdit: (item: SolveHistoryEntry) => void; onDelete: (item: SolveHistoryEntry) => void; labels: { moves: string; inspect: string; overTarget: string; plusTwo: string; dnf: string; playback: string; edit: string; remove: string } }) { return <article className="list-group-item"><div className="row g-3 align-items-center"><div className="col-auto"><input type="checkbox" checked={selected} onChange={onSelect} className="form-check-input" aria-label={`Select ${item.id}`} /></div><div className="col"><p className="font-monospace text-break mb-1">{item.input}</p><p className="small text-body-secondary mb-2">{new Date(item.createdAt).toLocaleString(vi ? "vi-VN" : "en-US")} · {item.moves} {labels.moves}{item.inspectionMs > 0 ? ` · ${labels.inspect} ${(item.inspectionMs / 1000).toFixed(2)}s` : ""}</p>{item.phaseSplits.length > 0 && <div className="d-flex flex-wrap gap-1 mb-2">{item.phaseSplits.map((split) => { const over = split.elapsedMs > phaseTargets[split.phase] * 1000; return <span key={split.phase} className={over ? "badge text-bg-danger" : "badge text-bg-success"}>{split.phase} {(split.elapsedMs / 1000).toFixed(2)}s{over ? ` · ${labels.overTarget}` : ""}</span>; })}</div>}{item.tags.length > 0 && <div className="d-flex flex-wrap gap-1 mb-2">{item.tags.map((tag) => <span key={tag} className="badge text-bg-secondary"><Tag className="fs-6 me-1" />{tag}</span>)}</div>}{item.note && <p className="small fst-italic text-body-secondary mb-0">{item.note}</p>}</div><div className="col-12 col-lg-auto d-flex flex-wrap align-items-center gap-1"><div className="btn-group btn-group-sm" role="group"><button type="button" onClick={() => onPenalty(item, "+2")} className={item.penalty === "+2" ? "btn btn-warning" : "btn btn-outline-secondary"}>{labels.plusTwo}</button><button type="button" onClick={() => onPenalty(item, "DNF")} className={item.penalty === "DNF" ? "btn btn-danger" : "btn btn-outline-secondary"}>{labels.dnf}</button></div><button type="button" disabled={!item.solution.trim()} onClick={() => onReplay(item)} className="btn btn-outline-secondary btn-sm" aria-label={labels.playback}><Play className="fs-6" /></button><button type="button" onClick={() => onEdit(item)} className="btn btn-outline-secondary btn-sm" aria-label={labels.edit}><Pencil className="fs-6" /></button><button type="button" onClick={() => onDelete(item)} className="btn btn-outline-danger btn-sm" aria-label={labels.remove}><Trash2 className="fs-6" /></button></div><div className="col-auto"><strong className={item.penalty === "DNF" ? "text-danger" : ""}>{formatSolveResult(item)}</strong></div></div></article>; }
